from itertools import combinations
import networkx as nx

top_neighbors = {
    0: {7,8,9}, 1: {7,10,11}, 2: {7,12,13},
    3: {8,10,12}, 4: {8,11,13}, 5: {9,10,13}, 6: {9,11,12}
}

# Check which pairs of top vertices share a bottom neighbor
conflicting_pairs_top = set()
for t1, t2 in combinations(range(7), 2):
    shared = top_neighbors[t1] & top_neighbors[t2]
    if shared:
        conflicting_pairs_top.add((t1,t2))

print("Conflicting pairs among top vertices:")
for p in sorted(conflicting_pairs_top):
    t1, t2 = p
    shared = top_neighbors[t1] & top_neighbors[t2]
    print(f"  {t1},{t2}: shared bottom={shared}")

print(f"\nTotal conflicting pairs: {len(conflicting_pairs_top)} out of {7*6//2} possible")
print("Is complete?", len(conflicting_pairs_top) == 7*6//2)
